-- General answers for questions customers often ask about a listing, a contract or the market.
-- They give the usual practice only; facts about a specific listing still come from the listing itself.
begin;
insert into public.kb_documents(source_type,title,body,metadata,published)
select 'Faq',v.title,v.body,'{"set":"faq50"}'::jsonb,true
from (values
('Diện tích thông thủy và diện tích tim tường khác nhau thế nào?','Diện tích tim tường tính từ tim tường bao và tường ngăn giữa các căn, nên lớn hơn. Diện tích thông thủy là phần sàn sử dụng thực tế, tính đến mép trong tường bao, không gồm cột và hộp kỹ thuật bên trong. Với căn hộ chung cư, sổ hồng ghi diện tích thông thủy. Khi tin đăng không ghi rõ, chuyên viên sẽ xác minh với chủ nhà hoặc hợp đồng mua bán.'),
('Giá thuê căn hộ đã gồm phí quản lý chưa?','Tùy thỏa thuận với chủ nhà. Thông thường giá thuê căn hộ chưa gồm phí quản lý, điện, nước, internet và phí gửi xe; một số chủ nhà để giá trọn gói. Nếu tin đăng không ghi rõ, chuyên viên sẽ hỏi chủ nhà trước khi khách xem nhà.'),
('Thuê nhà thường đặt cọc mấy tháng?','Mức cọc thuê nhà thường từ 1 đến 3 tháng tiền thuê, phổ biến là 1 hoặc 2 tháng, kèm thanh toán trước 1 đến 3 tháng tùy chủ nhà. Mức cụ thể, điều kiện hoàn cọc và kỳ thanh toán được ghi trong hợp đồng thuê.'),
('Có thể trả tiền thuê theo từng tháng không?','Nhiều chủ nhà nhận thanh toán theo tháng sau khi đã nhận cọc; một số yêu cầu trả trước 3 hoặc 6 tháng. Kỳ thanh toán được thỏa thuận khi ký hợp đồng, chuyên viên có thể đề xuất với chủ nhà theo nhu cầu của khách.'),
('Hợp đồng thuê nhà thường ký tối thiểu bao lâu?','Hợp đồng thuê căn hộ và nhà phố thường ký từ 6 đến 12 tháng. Thuê ngắn hạn 1 đến 3 tháng vẫn có thể có nếu chủ nhà đồng ý, giá thường cao hơn hoặc cần thanh toán trước toàn bộ thời gian thuê.'),
('Có cho thuê ngắn hạn vài tháng không?','Có thể, tùy từng chủ nhà. Phần lớn chủ nhà ưu tiên hợp đồng từ 6 tháng đến 1 năm; thuê ngắn hạn thường có giá cao hơn và cần trả trước. Khách cho biết thời gian thuê mong muốn, chuyên viên sẽ lọc các căn chủ nhà chấp nhận thuê ngắn hạn.'),
('Chuyển đi trước khi hết hợp đồng thuê có mất cọc không?','Phụ thuộc điều khoản chấm dứt hợp đồng. Thông thường nếu bên thuê tự ý chấm dứt trước hạn mà không báo trước theo thời hạn đã thỏa thuận (thường 30 ngày) thì có thể mất tiền cọc. Khách nên đọc kỹ điều khoản này hoặc thương lượng trước khi ký.'),
('Thuê lâu dài có được giảm giá không?','Có thể thương lượng. Khi ký hợp đồng dài hạn từ 1 năm trở lên hoặc thanh toán trước nhiều tháng, nhiều chủ nhà sẵn sàng giảm giá hoặc giữ giá không tăng trong thời gian thuê. Mức giảm cụ thể do chủ nhà quyết định; chuyên viên có thể đề xuất giúp khách.'),
('Căn hộ có cho nuôi thú cưng không?','Tùy quy định của chủ nhà và nội quy tòa nhà. Nhiều chung cư cho nuôi thú cưng nhỏ nếu đăng ký với ban quản lý và tuân thủ quy định chung; một số chủ nhà không đồng ý. Chuyên viên sẽ hỏi chủ nhà trước khi khách xem nhà.'),
('Hình ảnh tin đăng là hình thực tế hay minh họa?','Phần lớn tin đăng dùng hình chụp thực tế từ chủ nhà hoặc môi giới, nhưng hình có thể đã cũ hoặc nội thất đã thay đổi; tin dự án mới có thể dùng phối cảnh minh họa. Cách chắc chắn nhất là đặt lịch xem trực tiếp hoặc nhờ chuyên viên gửi thêm hình, video thực tế.'),
('Có thể xem thêm video thực tế của căn nhà không?','Chuyên viên phụ trách có thể quay hoặc xin chủ nhà video thực tế và gửi cho khách trước khi đi xem. Khách để lại yêu cầu tư vấn, chuyên viên sẽ liên hệ gửi video.'),
('Nội thất có đúng như hình đăng không?','Nội thất bàn giao được ghi trong hợp đồng thuê hoặc mua bán. Hình đăng có thể chưa cập nhật, vì vậy khách nên xem trực tiếp và yêu cầu ghi danh mục nội thất vào hợp đồng.'),
('Có thể gặp trực tiếp chủ nhà không?','Có thể. Sau khi khách xem nhà và có nhu cầu thật, chuyên viên sẽ sắp xếp buổi gặp chủ nhà để trao đổi giá và điều khoản. Thông tin liên hệ của chủ nhà không công khai trên website để bảo vệ quyền riêng tư.'),
('Có thể đi xem nhà vào cuối tuần không?','Có thể. Khách chọn căn quan tâm và gửi khung giờ mong muốn, kể cả thứ Bảy hoặc Chủ nhật. Chuyên viên sẽ liên hệ xác nhận lịch với chủ nhà trước khi lịch hẹn có hiệu lực.'),
('Mua nhà phải trả những thuế phí nào khi sang tên?','Khi chuyển nhượng thường có: thuế thu nhập cá nhân 2% giá chuyển nhượng (thường bên bán nộp), lệ phí trước bạ 0,5% giá trị tính lệ phí (thường bên mua nộp), phí công chứng theo biểu phí và phí thẩm định, cấp sổ. Bên nào nộp khoản nào có thể thỏa thuận trong hợp đồng. Số tiền chính xác phụ thuộc giá ghi trên hợp đồng và bảng giá đất.'),
('Có 1 tỷ thì có vay ngân hàng mua căn 3 tỷ được không?','Thường là được nếu đủ điều kiện. Ngân hàng hay cho vay khoảng 50% đến 70% giá trị tài sản tùy chính sách và thu nhập trả nợ. Với căn 3 tỷ và 1 tỷ tự có, khoản vay khoảng 2 tỷ (khoảng 67%) nên cần chứng minh thu nhập đủ trả gốc và lãi hằng tháng. Chuyên viên có thể kết nối ngân hàng đối tác để thẩm định cụ thể.'),
('Đặt cọc mua nhà mà ngân hàng không duyệt vay thì có lấy lại cọc không?','Phụ thuộc hợp đồng đặt cọc. Nếu hợp đồng có điều khoản hoàn cọc khi ngân hàng không giải ngân thì được lấy lại; nếu không có, bên mua tự ý không tiếp tục có thể mất cọc. Khách nên thẩm định khoản vay trước khi cọc và yêu cầu ghi rõ điều kiện này trong hợp đồng.'),
('Cần kiểm tra giấy tờ gì trước khi đặt cọc mua nhà?','Nên xem bản gốc sổ hồng hoặc giấy chứng nhận, đối chiếu thông tin chủ sở hữu với giấy tờ tùy thân, kiểm tra nhà có đang thế chấp hay tranh chấp không, tra cứu quy hoạch tại cơ quan nhà đất hoặc cổng thông tin quy hoạch, và với căn hộ dự án thì xem hợp đồng mua bán với chủ đầu tư cùng tiến độ thanh toán. Việc xác minh pháp lý cụ thể nên có công chứng viên hoặc luật sư hỗ trợ.'),
('Đất thổ cư và đất nông nghiệp khác nhau thế nào?','Đất thổ cư (đất ở) được xây nhà ở; đất nông nghiệp muốn xây nhà phải chuyển mục đích sử dụng và nộp tiền sử dụng đất. Loại đất và diện tích từng loại được ghi trên giấy chứng nhận. Nếu tin đăng không ghi rõ, chuyên viên sẽ kiểm tra sổ của lô đất.'),
('Làm sao biết lô đất có nằm trong quy hoạch hay tranh chấp không?','Có thể tra cứu quy hoạch qua cổng thông tin quy hoạch của thành phố, phòng quản lý đô thị hoặc văn phòng đăng ký đất đai, và xin xác nhận tình trạng tranh chấp tại UBND phường hoặc xã. Trước khi đặt cọc, chuyên viên có thể hỗ trợ kiểm tra cùng khách.'),
('Người nước ngoài có được mua căn hộ không?','Theo Luật Nhà ở 2023, cá nhân nước ngoài được nhập cảnh hợp pháp vào Việt Nam được mua căn hộ trong dự án nhà ở thương mại không thuộc khu vực bảo đảm quốc phòng, an ninh. Tổng số căn người nước ngoài sở hữu không quá 30% số căn của mỗi tòa nhà; thời hạn sở hữu tối đa 50 năm và có thể gia hạn. Chuyên viên sẽ kiểm tra dự án cụ thể còn chỉ tiêu cho người nước ngoài hay không.'),
('Mua căn hộ dự án thanh toán theo tiến độ thế nào?','Căn hộ hình thành trong tương lai được thanh toán theo các đợt ghi trong hợp đồng mua bán. Theo Luật Kinh doanh bất động sản 2023, lần thanh toán đầu kể cả tiền cọc không quá 30% giá trị hợp đồng, tổng số tiền trước khi bàn giao không quá 70%, và không quá 95% trước khi bên mua nhận giấy chứng nhận. Căn đã bàn giao thì thanh toán theo thỏa thuận với người bán.'),
('Làm sao biết dự án đã bàn giao hay đang xây?','Tình trạng bàn giao và tiến độ xây dựng được cập nhật từ chủ đầu tư. Tin đăng căn hộ đã có người ở, đang cho thuê hoặc ghi có sổ hồng thường thuộc dự án đã bàn giao. Chuyên viên có thể gửi thông tin tiến độ mới nhất của dự án.'),
('Quy trình đặt cọc và ký hợp đồng mua nhà gồm những bước nào?','Thường gồm: xem nhà và kiểm tra pháp lý; thống nhất giá, tiến độ thanh toán và thời hạn bàn giao; ký hợp đồng đặt cọc (thường khoảng 5% đến 10% giá trị); ký hợp đồng mua bán có công chứng; thanh toán theo tiến độ; làm thủ tục sang tên và nộp thuế phí; bàn giao nhà. Chuyên viên sẽ đồng hành từng bước.'),
('Nên đầu tư đất nền hay căn hộ?','Đất nền thường có tiềm năng tăng giá dài hạn, ít chi phí duy trì nhưng thanh khoản chậm hơn, không tạo dòng tiền cho thuê ngay và cần kiểm tra kỹ pháp lý, quy hoạch. Căn hộ dễ cho thuê tạo dòng tiền đều, thanh khoản tốt hơn ở dự án đã bàn giao nhưng có phí quản lý và hao mòn. Lựa chọn phụ thuộc vốn, thời gian nắm giữ và nhu cầu dòng tiền; chuyên viên có thể so sánh cụ thể theo ngân sách.'),
('Mua căn hộ để cho thuê thì tính lợi nhuận thế nào?','Lợi suất cho thuê được tính bằng tiền thuê một năm chia cho giá mua. Nên so sánh với các căn cho thuê tương tự trong cùng dự án hoặc khu vực, trừ phí quản lý, thời gian trống và chi phí sửa chữa để ra lợi nhuận thực tế.'),
('Tìm thuê nhà có chỗ để xe máy không?','Phần lớn chung cư và nhà nguyên căn có chỗ để xe máy; chung cư thường thu phí gửi xe theo tháng do ban quản lý quy định. Phòng trọ hoặc nhà trong hẻm nhỏ cần hỏi kỹ chỗ để xe và giờ ra vào.')
) as v(title,body)
where not exists(select 1 from public.kb_documents d where d.source_type='Faq' and d.title=v.title);
commit;
